final readonly class FeatureFlags
{
    public function __construct(
        private FlagRepository $flags,
        private CacheInterface $cache,
    ) {
    }

    public function isOn(string $name, ?User $user = null): bool
    {
        $flag = $this->cache->get("flag.$name", function (ItemInterface $item) use ($name) {
            $item->expiresAfter(30);     // a switch change reaches every server in 30s

            return $this->flags->snapshot($name);   // missing: ['enabled' => false, ...]
        });

        if (!$flag['enabled'] || null === $user) {
            return $flag['enabled'] && 100 === $flag['percent'];
        }

        return \in_array($user->getId(), $flag['allow'], true)
            || crc32($name.':'.$user->getId()) % 100 < $flag['percent'];
    }
}

