public function testNoReleaseFlagIsPastItsRemovalDate(): void
{
    $flags = Yaml::parseFile(__DIR__.'/../../config/flags.yaml');
    $today = new \DateTimeImmutable('today');
    $overdue = [];

    foreach ($flags as $name => $flag) {
        if ('release' !== $flag['type']) {
            continue;
        }
        if (new \DateTimeImmutable($flag['remove_by']) < $today) {
            $overdue[] = $name;
        }
    }

    self::assertSame([], $overdue, 'Overdue flags: delete them and their old paths.');
}

