final class DiscountEngine
{
    private ExpressionLanguage $language;

    public function __construct(private readonly DiscountRuleRepository $rules)
    {
        $this->language = new ExpressionLanguage();
    }

    public function percentFor(CartFacts $cart, UserFacts $user): int
    {
        foreach ($this->rules->activeByPriority() as $rule) {
            $facts = ['cart' => $cart, 'user' => $user];
            if ($this->language->evaluate($rule->expression(), $facts)) {
                return min($rule->percent(), 30);   // the cap lives in code
            }
        }

        return 0;
    }
}

public function assertValid(string $expression): void
{
    try {
        $this->language->lint($expression, ['cart', 'user']);
    } catch (SyntaxError $e) {
        throw new InvalidRuleException('Invalid condition: '.$e->getMessage(), previous: $e);
    }
}

#[DataProvider('cases')]
public function testRule(string $expr, int $total, bool $first, bool $expected): void
{
    $result = (new ExpressionLanguage())->evaluate($expr, [
        'cart' => new CartFacts($total, 3),
        'user' => new UserFacts($first),
    ]);

    self::assertSame($expected, $result);
}

