public function dryRun(array $candidateRules, int $days = 30): DryRunReport
{
    $changed = 0;
    $extraDollars = 0;

    foreach ($this->orders->placedWithinDays($days) as $order) {
        $given = $order->discountPercent();      // what customers really got
        $would = $this->engine->percentUsing($candidateRules, $order->cart(), $order->user());
        if ($would !== $given) {
            ++$changed;
            $extraDollars += intdiv($order->totalInCents() * ($would - $given), 10_000);
        }
    }

    return new DryRunReport($changed, $extraDollars);
}

